/** Parser :: Parse To: header.
 * @file
 * @ingroup parser
 */

#include "parse_to.h"
#include <stdlib.h>
#include <string.h>
#include "../dprint.h"
#include "msg_parser.h"
#include "parse_uri.h"
#include "../ut.h"
#include "../mem/mem.h"


enum
{
        START_TO,
        DISPLAY_QUOTED,
        E_DISPLAY_QUOTED,
        DISPLAY_TOKEN,
        DISPLAY_TOKEN_SP,
        S_URI_ENCLOSED,
        URI_ENCLOSED,
        E_URI_ENCLOSED,
        URI_OR_TOKEN,
        MAYBE_URI_END,
        END,
        F_CR,
        F_LF,
        F_CRLF
};


enum
{
        S_PARA_NAME = 20,
        PARA_NAME,
        S_EQUAL,
        S_PARA_VALUE,
        TAG1,
        TAG2,
        TAG3,
        PARA_VALUE_TOKEN,
        PARA_VALUE_QUOTED,
        E_PARA_VALUE
};


#define add_param(_param, _body, _newparam)                                   \
        do {                                                                      \
                LM_DBG("add param: %.*s=%.*s\n", param->name.len, ZSW(param->name.s), \
                                param->value.len, ZSW(param->value.s));                       \
                if(!(_body)->param_lst)                                               \
                        (_body)->param_lst = (_param);                                    \
                else                                                                  \
                        (_body)->last_param->next = (_param);                             \
                (_body)->last_param = (_param);                                       \
                if((_param)->type == TAG_PARAM)                                       \
                        memcpy(&((_body)->tag_value), &((_param)->value), sizeof(str));   \
                _newparam = 0;                                                        \
        } while(0);


static char *parse_to_param(char *const buffer, const char *const end,
                struct to_body *const to_b, const int allow_comma_sep,
                int *const returned_status)
{
        struct to_param *param;
        struct to_param *newparam;
        int status;
        int saved_status;
        char *tmp;

        param = 0;
        newparam = 0;
        status = E_PARA_VALUE;
        saved_status = E_PARA_VALUE;
        for(tmp = buffer; tmp < end; tmp++) {
                switch(*tmp) {
                        case ' ':
                        case '\t':
                                switch(status) {
                                        case TAG3:
                                                param->type = TAG_PARAM;
                                        case PARA_NAME:
                                        case TAG1:
                                        case TAG2:
                                                param->name.len = tmp - param->name.s;
                                                status = S_EQUAL;
                                                break;
                                        case PARA_VALUE_TOKEN:
                                                param->value.len = tmp - param->value.s;
                                                status = E_PARA_VALUE;
                                                add_param(param, to_b, newparam);
                                                break;
                                        case F_CRLF:
                                        case F_LF:
                                        case F_CR:
                                                /*previous=crlf and now =' '*/
                                                status = saved_status;
                                                break;
                                }
                                break;
                        case '\n':
                                switch(status) {
                                        case S_PARA_NAME:
                                        case S_EQUAL:
                                        case S_PARA_VALUE:
                                        case E_PARA_VALUE:
                                                saved_status = status;
                                                status = F_LF;
                                                break;
                                        case TAG3:
                                                param->type = TAG_PARAM;
                                        case PARA_NAME:
                                        case TAG1:
                                        case TAG2:
                                                param->name.len = tmp - param->name.s;
                                                saved_status = S_EQUAL;
                                                status = F_LF;
                                                break;
                                        case PARA_VALUE_TOKEN:
                                                param->value.len = tmp - param->value.s;
                                                saved_status = E_PARA_VALUE;
                                                status = F_LF;
                                                add_param(param, to_b, newparam);
                                                break;
                                        case F_CR:
                                                status = F_CRLF;
                                                break;
                                        case F_CRLF:
                                        case F_LF:
                                                status = saved_status;
                                                goto endofheader;
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), ZSW(buffer));
                                                goto error;
                                }
                                break;
                        case '\r':
                                switch(status) {
                                        case S_PARA_NAME:
                                        case S_EQUAL:
                                        case S_PARA_VALUE:
                                        case E_PARA_VALUE:
                                                saved_status = status;
                                                status = F_CR;
                                                break;
                                        case TAG3:
                                                param->type = TAG_PARAM;
                                        case PARA_NAME:
                                        case TAG1:
                                        case TAG2:
                                                param->name.len = tmp - param->name.s;
                                                saved_status = S_EQUAL;
                                                status = F_CR;
                                                break;
                                        case PARA_VALUE_TOKEN:
                                                param->value.len = tmp - param->value.s;
                                                saved_status = E_PARA_VALUE;
                                                status = F_CR;
                                                add_param(param, to_b, newparam);
                                                break;
                                        case F_CRLF:
                                        case F_CR:
                                        case F_LF:
                                                status = saved_status;
                                                goto endofheader;
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), ZSW(buffer));
                                                goto error;
                                }
                                break;
                        case 0:
                                switch(status) {
                                        case TAG3:
                                                param->type = TAG_PARAM;
                                        case PARA_NAME:
                                        case TAG1:
                                        case TAG2:
                                                param->name.len = tmp - param->name.s;
                                                status = S_EQUAL;
                                        case S_EQUAL:
                                        case S_PARA_VALUE:
                                                saved_status = status;
                                                goto endofheader;
                                        case PARA_VALUE_TOKEN:
                                                status = E_PARA_VALUE;
                                                param->value.len = tmp - param->value.s;
                                                add_param(param, to_b, newparam);
                                        case E_PARA_VALUE:
                                                saved_status = status;
                                                goto endofheader;
                                                break;
