                                break;
                        case '>':
                                switch(status) {
                                        case DISPLAY_QUOTED:
                                                break;
                                        case URI_ENCLOSED:
                                                to_b->uri.len = tmp - to_b->uri.s;
                                        case E_URI_ENCLOSED:
                                                status = END;
                                                foo = 0;
                                                break;
                                        case F_CRLF:
                                        case F_LF:
                                        case F_CR:
                                                /*previous=crlf and now !=' '*/
                                                goto endofheader;
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), ZSW(buffer));
                                                goto error;
                                }
                                break;
                        case '"':
                                switch(status) {
                                        case START_TO:
                                                to_b->body.s = tmp;
                                                to_b->display.s = tmp;
                                                status = DISPLAY_QUOTED;
                                                break;
                                        case DISPLAY_QUOTED:
                                                status = E_DISPLAY_QUOTED;
                                                to_b->display.len = tmp - to_b->display.s + 1;
                                                break;
                                        case F_CRLF:
                                        case F_LF:
                                        case F_CR:
                                                /*previous=crlf and now !=' '*/
                                                goto endofheader;
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), buffer);
                                                goto error;
                                }
                                break;
                        case ';':
                                switch(status) {
                                        case DISPLAY_QUOTED:
                                        case URI_ENCLOSED:
                                                break;
                                        case URI_OR_TOKEN:
                                                foo = tmp;
                                        case MAYBE_URI_END:
                                                to_b->uri.len = foo - to_b->uri.s;
                                        case END:
                                                to_b->body.len = tmp - to_b->body.s;
                                                tmp = parse_to_param(
                                                                tmp, end, to_b, allow_comma_sep, &saved_status);
                                                goto endofheader;
                                        case F_CRLF:
                                        case F_LF:
                                        case F_CR:
                                                /*previous=crlf and now !=' '*/
                                                goto endofheader;
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), buffer);
                                                goto error;
                                }
                                break;
                        case ',':
                                if(allow_comma_sep) {
                                        switch(status) {
                                                case DISPLAY_QUOTED:
                                                case URI_ENCLOSED:
                                                        break;
                                                case URI_OR_TOKEN:
                                                        foo = tmp;
                                                case MAYBE_URI_END:
                                                        to_b->uri.len = foo - to_b->uri.s;
                                                case END:
                                                        to_b->body.len = tmp - to_b->body.s;
                                                        saved_status = END;
                                                        goto endofheader;
                                                case F_CRLF:
                                                case F_LF:
                                                case F_CR:
                                                        /*previous=crlf and now !=' '*/
                                                        goto endofheader;
                                                default:
                                                        LM_ERR("unexpected char [%c] in status %d: [%.*s] "
                                                                        ".\n",
                                                                        *tmp, status, (int)(tmp - buffer), buffer);
                                                        goto error;
                                        }
                                        break;
                                }
                        /* If commas not allowed treat as a default character */
                        default:
                                switch(status) {
                                        case START_TO:
                                                to_b->uri.s = to_b->body.s = tmp;
                                                status = URI_OR_TOKEN;
                                                to_b->display.s = tmp;
                                                break;
                                        case S_URI_ENCLOSED:
                                                to_b->uri.s = tmp;
                                                status = URI_ENCLOSED;
                                                break;
                                        case MAYBE_URI_END:
                                        case DISPLAY_TOKEN_SP:
                                                status = DISPLAY_TOKEN;
